import math
import unittest

from solution import measure


class SinglePassIterable:
    def __init__(self, values):
        self.values = list(values)
        self.iterations = 0

    def __iter__(self):
        self.iterations += 1
        if self.iterations > 1:
            raise AssertionError("iterable consumed more than once")
        yield from self.values


class MeasureTests(unittest.TestCase):
    def test_empty_and_integer_inputs(self):
        self.assertEqual(measure([]), (0, 0, 0))
        self.assertEqual(measure([1, 2, 3]), (3, 6, 2.0))

    def test_mixed_numeric_values_and_normal_arithmetic(self):
        result = measure((1, 2.5, -0.5))
        self.assertEqual(result, (3, 3.0, 1.0))
        count, total, mean = measure([1, 2])
        self.assertEqual(count, 2)
        self.assertIsInstance(total, int)
        self.assertEqual(mean, 1.5)

    def test_generator_is_consumed_once(self):
        source = SinglePassIterable([4, 6.0])
        self.assertEqual(measure(source), (2, 10.0, 5.0))
        self.assertEqual(source.iterations, 1)

    def test_container_is_not_mutated(self):
        values = [3, 1, 2]
        self.assertEqual(measure(values), (3, 6, 2.0))
        self.assertEqual(values, [3, 1, 2])

    def test_non_iterable_and_non_numeric_elements(self):
        with self.assertRaises(TypeError):
            measure(123)
        for bad in (True, False, "3", None, object()):
            with self.subTest(bad=bad):
                with self.assertRaises(TypeError):
                    measure([1, bad])

    def test_non_finite_numbers(self):
        for bad in (math.nan, math.inf, -math.inf):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    measure([0, bad])

    def test_has_descriptive_docstring(self):
        self.assertIsInstance(measure.__doc__, str)
        self.assertTrue(measure.__doc__.strip())
        self.assertGreaterEqual(len(measure.__doc__.split()), 3)


if __name__ == "__main__":
    unittest.main()

